"use client";

import { usePathname } from "next/navigation";
import {
  Skeleton,
  WorkspaceSkeleton,
  type WorkspacePage,
} from "@/components/workspace-skeleton";

export function WorkspaceLoading({ shell = false }: { shell?: boolean }) {
  const pathname = usePathname();
  const page = pathname.split("/")[1];
  const current: WorkspacePage = [
    "compose",
    "templates",
    "history",
    "contacts",
    "settings",
    "billing",
  ].includes(page)
    ? (page as WorkspacePage)
    : "compose";
  if (!shell)
    return (
      <div className={current === "compose" ? "compose-page" : undefined}>
        <WorkspaceSkeleton page={current} />
      </div>
    );
  return (
    <div className={current === "compose" ? "compose-page" : undefined}>
      <div className="page-container pt-[18px]" aria-hidden="true">
        <div className="flex min-h-[54px] items-center justify-between gap-3">
          <Skeleton className="h-8 w-36" />
          <Skeleton className="h-[54px] w-40" />
        </div>
        <div className="workspace-nav-wrap [container-type:inline-size] w-full mt-3">
          <div className="workspace-nav relative isolate flex items-center flex-nowrap overflow-x-auto [scrollbar-width:none] gap-[0.15em] w-max max-w-full text-[clamp(14px,_1.75cqw,_17px)] p-[0.32em] [border:1px_solid_var(--nav-line)] rounded-full [background:var(--nav-bg)] shadow-none">
            {Array.from({ length: 6 }, (_, index) => (
              <Skeleton
                key={index}
                className="workspace-nav-placeholder h-11 w-[7em] shrink-0 rounded-full"
              />
            ))}
          </div>
        </div>
      </div>
      <main id="main-content" className="page-container pt-[26px] pb-[60px]">
        <WorkspaceSkeleton page={current} />
      </main>
    </div>
  );
}
